corrected_code:
package learning

import (
	"context"
	"github.com/jmoiron/sqlx"
	"myapp/auth"
	"myapp/models"
)

type CertStore struct {
	DB *sqlx.DB
}

func (s *CertStore) GetCertificateDetails(ctx context.Context, certNumber string) (*models.Certificate, error) {
	var cert models.Certificate
	studentID := auth.GetStudentID(ctx)

	query := `SELECT cert_number, student_id, course_title, completion_date FROM certificates WHERE cert_number = $1 AND student_id = $2`
	if err := s.DB.GetContext(ctx, &cert, query, certNumber, studentID); err != nil {
		return nil, err
	}

	return &cert, nil
}
